import pandas as pd
import numpy as np
import itertools

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Determine the maximum length of any tuple
    max_len = max(len(t) for t in data_list)

    means = []
    for pos in range(max_len):
        values = []
        for t in data_list:
            if pos < len(t):
                val = t[pos]
                if isinstance(val, (int, float)) and not isinstance(val, bool):
                    values.append(val)
                elif isinstance(val, str):
                    try:
                        f = float(val)
                        values.append(f)
                    except (ValueError, TypeError):
                        pass
        if values:
            means.append(np.mean(values))
        else:
            means.append(np.nan)

    index = [f"Position {i}" for i in range(len(means))]
    df = pd.DataFrame({'Mean Value': means}, index=index)
    return df

