def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    # Create destination directory if it doesn't exist
    if not os.path.exists(DEST_DIR):
        os.makedirs(DEST_DIR)

    # Get all files in source directory
    for file_name in os.listdir(SOURCE_DIR):
        # Check if file has one of the specified extensions
        if any(file_name.lower().endswith(ext.lower()) for ext in EXTENSIONS):
            source_path = os.path.join(SOURCE_DIR, file_name)
            dest_path = os.path.join(DEST_DIR, file_name)

            if os.path.isfile(source_path):
                try:
                    shutil.copy2(source_path, dest_path)
                    transferred_files.append(file_name)
                except Exception as e:
                    warnings.warn(f"Failed to transfer file {file_name}: {str(e)}")

    return transferred_files

import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("n_tasks cannot be negative")

    if seed is not None:
        random.seed(seed)

    current_date = datetime.now().strftime('%Y-%m-%d')

    if n_tasks == 0:
        return pd.DataFrame({
            'Task Name': [],
            'Assigned To': [],
            'Due Date': []
        })

    # Randomly select n_tasks from task_list (with replacement)
    selected_tasks = random.choices(task_list, k=n_tasks)

    # Assign each task to a random employee
    assignments = []
    for task in selected_tasks:
        employee = random.choice(employees)
        sanitized_task = task.replace(' ', '_')
        assignments.append({
            'Task Name': sanitized_task,
            'Assigned To': employee,
            'Due Date': current_date
        })

    return pd.DataFrame(assignments)

